package com.servicerca.service;import com.servicerca.dto.common.PageResponse;import com.servicerca.dto.notification.AppNotificationResponse;import com.servicerca.exception.ResourceNotFoundException;import com.servicerca.model.*;import com.servicerca.repository.AppNotificationRepository;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.UUID;@Service public class InAppNotificationService{private final AppNotificationRepository repo;public InAppNotificationService(AppNotificationRepository r){repo=r;}@Transactional public void create(User u,ServiceRequest r,String type,String message){repo.save(AppNotification.builder().user(u).request(r).type(type).message(message).build());}@Transactional(readOnly=true)public PageResponse<AppNotificationResponse>list(User u,int page,int size){var p=repo.findByUserIdOrderByCreatedAtDesc(u.getId(),PageRequest.of(Math.max(0,page),Math.min(Math.max(size,1),50))).map(this::view);return PageResponse.of(p);}@Transactional public AppNotificationResponse read(User u,UUID id){var n=repo.findByIdAndUserId(id,u.getId()).orElseThrow(()->new ResourceNotFoundException("Notificación inexistente."));if(n.getReadAt()==null)n.setReadAt(Instant.now());return view(n);}private AppNotificationResponse view(AppNotification n){return new AppNotificationResponse(n.getId(),n.getRequest()==null?null:n.getRequest().getId(),n.getType(),n.getMessage(),n.getCreatedAt(),n.getReadAt()!=null);}}
